1	'use client';
2	
3	import React, { useCallback, useEffect, useState } from 'react';
4	import Link from 'next/link';
5	import { useAuth } from '@/context/AuthContext';
6	import { useLanguage } from '../lib/i18n';
7	import { databases, DB_ID, TABLE_ID } from '@/lib/appwrite';
8	import { appwriteConfigMissing } from '@/lib/app-config';
9	import { Query } from 'appwrite';
10	import type { AppDocument } from '@/lib/types';
11	import { Smartphone, ExternalLink, Download, Plus, Loader2, ArrowRight, CheckCircle2, Clock, Play, X, Hammer, HelpCircle } from 'lucide-react';
12	
13	const BUILD_TIMEOUT_MS = 20 * 60 * 1000;
14	const buildStartedStorageKey = (appId: string) => `appifya_build_started_${appId}`;
15	const statusUrl = (appId: string) => {
16	  const startedAt = localStorage.getItem(buildStartedStorageKey(appId));
17	  const query = new URLSearchParams({ appId });
18	  if (startedAt) query.set('startedAt', new Date(Number(startedAt)).toISOString());
19	  return `/api/build-apk?${query.toString()}`;
20	};
21	
22	export default function DashboardPage() {
23	  const { user, loading: authLoading, openAuthModal } = useAuth();
24	  const { lang } = useLanguage();
25	  const [apps, setApps] = useState<AppDocument[]>([]);
26	  const [loading, setLoading] = useState(true);
27	  const [buildingAppId, setBuildingAppId] = useState<string | null>(null);
28	  const [buildNoticeAppId, setBuildNoticeAppId] = useState<string | null>(null);
29	  const [builds, setBuilds] = useState<Record<string, { status: 'building' | 'completed' | 'failed'; downloadUrl?: string }>>({});
30	
31	  const isRtl = lang === 'ar';
32	
33	  const clearBuildStart = (appId: string) => {
34	    localStorage.removeItem(buildStartedStorageKey(appId));
35	  };
36	
37	  const markBuildStarted = (appId: string) => {
38	    // This runs only after a user starts a build.
39	    // eslint-disable-next-line react-hooks/purity
40	    localStorage.setItem(buildStartedStorageKey(appId), String(Date.now()));
41	  };
42	
43	  const getBuildStartedAt = (appId: string) => {
44	    const value = Number(localStorage.getItem(buildStartedStorageKey(appId)));
45	    return Number.isFinite(value) && value > 0 ? value : null;
46	  };
47	
48	  const loadUserApps = useCallback(async () => {
49	    if (!user) return;
50	    try {
51	      setLoading(true);
52	      const res = await databases.listDocuments(DB_ID, TABLE_ID, [
53	        Query.equal('user_id', user.$id),
54	        Query.orderDesc('$createdAt'),
55	      ]);
56	      setApps(res.documents);
57	    } catch (err) {
58	      console.error('Error:', err);
59	    } finally {
60	      setLoading(false);
61	    }
62	  }, [user]);
63	
64	  useEffect(() => {
65	    if (!authLoading && !user) {
66	      openAuthModal();
67	    } else if (user) {
68	      // Loading the user's remote documents is an external synchronization effect.
69	      // eslint-disable-next-line react-hooks/set-state-in-effect
70	      loadUserApps();
71	    }
72	  }, [user, authLoading, loadUserApps]);
73	
74	  useEffect(() => {
75	    if (apps.length === 0) return;
76	
77	    const restoreBuildStatuses = async () => {
78	      await Promise.all(apps.map(async (app) => {
79	        try {
80	          const response = await fetch(statusUrl(app.$id), { cache: 'no-store' });
81	          if (!response.ok) return;
82	
83	          const result = await response.json();
84	          if (result.status === 'building' || result.status === 'completed' || result.status === 'failed') {
85	            const startedAt = getBuildStartedAt(app.$id);
86	            const isStale = result.status === 'building'
87	              && (!startedAt || Date.now() - startedAt > BUILD_TIMEOUT_MS);
88	            setBuilds((current) => ({
89	              ...current,
90	              [app.$id]: {
91	                status: isStale ? 'failed' : result.status,
92	                downloadUrl: result.downloadUrl,
93	              },
94	            }));
95	            if (isStale) {
96	              clearBuildStart(app.$id);
97	            } else if (result.status === 'building') {
98	              setBuildNoticeAppId(app.$id);
99	            }
100	          }
101	        } catch (error) {
102	          console.error('Build status restore failed:', error);
103	        }
104	      }));
105	    };
106	
107	    void restoreBuildStatuses();
108	  }, [apps]);
109	
110	  const handleTriggerBuild = async (app: AppDocument) => {
111	    try {
112	      setBuildingAppId(app.$id);
113	      const res = await fetch('/api/build-apk', {
114	        method: 'POST',
115	        headers: { 'Content-Type': 'application/json' },
116	        body: JSON.stringify({ appId: app.$id, userId: user?.$id }),
117	      });
118	
119	      const data = await res.json();
120	      if (res.ok) {
121	        markBuildStarted(app.$id);
122	        setBuilds((current) => ({ ...current, [app.$id]: { status: 'building' } }));
123	        setBuildNoticeAppId(app.$id);
124	      } else {
125	        alert(data.error || 'فشل إرسال طلب البناء، يرجى المحاولة مرة أخرى.');
126	      }
127	    } catch {
128	      alert('تعذر الاتصال بالسيرفر لبدء البناء');
129	    } finally {
130	      setBuildingAppId(null);
131	    }
132	  };
133	
134	  useEffect(() => {
135	    const activeIds = Object.entries(builds)
136	      .filter(([, build]) => build.status === 'building')
137	      .map(([id]) => id);
138	    if (activeIds.length === 0) return;
139	
140	    const checkBuilds = async () => {
141	      await Promise.all(activeIds.map(async (appId) => {
142	        try {
143	          const response = await fetch(statusUrl(appId), { cache: 'no-store' });
144	          if (!response.ok) return;
145	          const result = await response.json();
146	          const startedAt = getBuildStartedAt(appId);
147	          const isStale = result.status === 'building'
148	            && (!startedAt || Date.now() - startedAt > BUILD_TIMEOUT_MS);
149	          if (isStale || result.status === 'completed' || result.status === 'failed') {
150	            setBuilds((current) => ({
151	              ...current,
152	              [appId]: {
153	                status: isStale ? 'failed' : result.status,
154	                downloadUrl: result.downloadUrl,
155	              },
156	            }));
157	            setBuildNoticeAppId((current) => (current === appId ? null : current));
158	            if (isStale) clearBuildStart(appId);
159	          }
160	        } catch (error) {
161	          console.error('Build status check failed:', error);
162	        }
163	      }));
164	    };
165	
166	    void checkBuilds();
167	    const interval = window.setInterval(checkBuilds, 10000);
168	    return () => window.clearInterval(interval);
169	  }, [builds]);
170	
171	  const labels = {
172	    title: { ar: 'لوحة تحكم تطبيقاتي', en: 'My Applications', fr: 'Mes Applications' },
173	    welcome: {
174	      ar: 'مرحباً بك، إليك جميع التطبيقات التي أنشأتها عبر Appifya.',
175	      en: 'Welcome! Here are all the apps you have created with Appifya.',
176	      fr: 'Bienvenue ! Voici toutes les applications que vous avez créées avec Appifya.',
177	    },
178	    newApp: { ar: 'إنشاء تطبيق جديد', en: 'Create New App', fr: 'Nouvelle Application' },
179	    emptyTitle: { ar: 'لا توجد تطبيقات محفوظة بعد', en: 'No apps saved yet', fr: 'Aucune application trouvée' },
180	    emptyDesc: {
181	      ar: 'ابدأ الآن بتحويل متجرك الإلكتروني أو صفحة الهبوط إلى تطبيق أندرويد و PWA احترافي خلال دقائق.',
182	      en: 'Start converting your store or landing page into an Android App and PWA in minutes.',
183	      fr: 'Transformez votre boutique en application Android et PWA en quelques minutes.',
184	    },
185	    createFirst: { ar: 'إنشاء أول تطبيق لك', en: 'Create your first app', fr: 'Créer votre première app' },
186	    preview: { ar: 'معاينة المتجر', en: 'Preview Store', fr: 'Aperçu du site' },
187	    buildApk: { ar: 'بناء ملف APK', en: 'Build APK', fr: 'Compiler APK' },
188	    downloadApk: { ar: 'تنزيل APK', en: 'Download APK', fr: 'Télécharger APK' },
189	    active: { ar: 'نشط ومتصل بالسحابة', en: 'Cloud Synced & Active', fr: 'Actif & Synchronisé' },
190	    noName: { ar: 'تطبيق بدون اسم', en: 'Untitled App', fr: 'Application sans titre' },
191	    loginReq: { ar: 'يرجى تسجيل الدخول للوصول إلى لوحة التحكم', en: 'Please sign in to access your dashboard', fr: 'Veuillez vous connecter pour accéder au tableau de bord' },
192	    signInBtn: { ar: 'تسجيل الدخول الآن', en: 'Sign In Now', fr: 'Se connecter maintenant' },
193	    buildNoticeTitle: { ar: 'جاري تجهيز تطبيقك', en: 'Your app is being built', fr: 'Votre application est en cours de création' },
194	    buildNoticeText: {
195	      ar: 'تم إرسال الطلب بنجاح إلى خوادم البناء. يمكنك إغلاق هذه النافذة؛ سنواصل العمل في الخلفية ويظهر زر التنزيل تلقائياً عند الجاهزية.',
196	      en: 'Your request was sent successfully to the build servers. You can close this window; the build continues in the background and the download button will appear when ready.',
197	      fr: 'Votre demande a été envoyée aux serveurs de compilation. Vous pouvez fermer cette fenêtre : le traitement continue en arrière-plan et le bouton de téléchargement apparaîtra dès que le fichier sera prêt.',
198	    },
199	    buildNoticeStatus: { ar: 'جاري إنشاء ملف APK', en: 'Building APK', fr: 'Compilation de l’APK' },
200	    close: { ar: 'متابعة في الخلفية', en: 'Continue in background', fr: 'Continuer en arrière-plan' },
201	    buildStarting: { ar: 'جاري البدء...', en: 'Starting...', fr: 'Démarrage...' },
202	    buildStuck: {
203	      ar: 'تعذر إكمال البناء. يمكنك المحاولة مرة أخرى.',
204	      en: 'The build timed out. You can try again.',
205	      fr: 'La compilation a expiré. Vous pouvez réessayer.',
206	    },
207	  };
208	
209	  const getTxt = (key: keyof typeof labels) => labels[key][lang] || labels[key]['en'];
210	
211	  if (authLoading) {
212	    return (
213	      <div className="flex-1 flex items-center justify-center p-12">
214	        <Loader2 className="h-8 w-8 animate-spin text-indigo-500" />
215	      </div>
216	    );
217	  }
218	
219	  if (appwriteConfigMissing.length > 0) {
220	    return (
221	      <main className="flex-1 flex items-center justify-center p-12 text-center" dir={isRtl ? 'rtl' : 'ltr'}>
222	        <div className="max-w-lg">
223	          <h2 className="text-xl font-bold text-white mb-3">إعدادات التطبيق غير مكتملة</h2>
224	          <p className="text-sm text-slate-400">
225	            يرجى إضافة متغيرات Appwrite الناقصة في إعدادات الاستضافة ثم إعادة النشر.
226	          </p>
227	        </div>
228	      </main>
229	    );
230	  }
231	
232	  if (!user) {
233	    return (
234	      <div className="flex-1 flex flex-col items-center justify-center p-12 text-center" dir={isRtl ? 'rtl' : 'ltr'}>
235	        <Smartphone className="h-12 w-12 text-indigo-400 mb-4" />
236	        <h2 className="text-xl font-bold text-white mb-2">{getTxt('loginReq')}</h2>
237	        <button
238	          onClick={() => openAuthModal()}
239	          className="mt-4 px-6 py-2.5 bg-indigo-600 hover:bg-indigo-500 text-white font-semibold rounded-xl text-sm shadow-lg shadow-indigo-500/20"
240	        >
