254	              onClick={() => setBuildNoticeAppId(null)}
255	              className="absolute right-4 top-4 rounded-lg p-2 text-slate-500 transition hover:bg-slate-800 hover:text-white"
256	              aria-label={getTxt('close')}
257	            >
258	              <X className="h-5 w-5" />
