280	      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-8 border-b border-slate-800 pb-6">
281	        <div>
282	          <h1 className="text-2xl font-extrabold text-white">{getTxt('title')}</h1>
283	          <p className="text-xs text-slate-400 mt-1">
284	            <span className="text-indigo-400 font-semibold">{user.name || user.email}</span>, {getTxt('welcome')}
