332	                    </p>
333	                  </div>
334	                </div>
335	
336	                <div className="flex items-center gap-2 mb-4 text-[11px]">
337	                  <span className="px-2 py-0.5 rounded-md bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 font-medium">
