342	                  </span>
343	                </div>
344	              </div>
345	
346	              <div className="flex items-center gap-2 pt-4 border-t border-slate-800/80">
347	                <a
348	                  href={app.store_url}
349	                  target="_blank"
350	                  rel="noopener noreferrer"
351	                  className="flex-1 flex items-center justify-center gap-1.5 py-2 bg-slate-800 hover:bg-slate-700 text-white text-xs font-semibold rounded-xl transition-colors"
352	                >
353	                  <ExternalLink className="h-3.5 w-3.5" />
354	                  <span>{getTxt('preview')}</span>
355	                </a>
356	
357	                <button
358	                  onClick={() => handleTriggerBuild(app)}
