377	              {builds[app.$id]?.status === 'failed' && (
378	                <div className="mt-3 flex items-center gap-2 text-[11px] text-rose-500">
379	                  <X className="h-3.5 w-3.5" />
380	                  <span>{getTxt('buildStuck')}</span>
381	                </div>
382	              )}
383	              {builds[app.$id]?.status === 'completed' && builds[app.$id]?.downloadUrl && (
384	                <div className="mt-3 flex flex-col gap-2">
385	                  <a
386	                    href={builds[app.$id].downloadUrl}
387	                    className="flex items-center justify-center gap-2 py-2 bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-semibold rounded-xl"
388	                  >
389	                    <Download className="h-3.5 w-3.5" />
390	                    <span>{getTxt('downloadApk')}</span>
391	                  </a>
392	                  <Link
393	                    href="/guide"
