      <div className="bg-gradient-to-r from-indigo-900/30 to-pink-900/30 border border-indigo-500/30 rounded-3xl p-8 text-center space-y-4">
        <h2 className="text-xl font-bold text-white">
          {lang === 'ar'
            ? 'هل أنجزت التثبيت بنجاح؟'
            : lang === 'fr'
            ? 'Installation réussie ?'
            : 'Installation complete?'}
        </h2>
        <p className="text-sm text-slate-400 max-w-md mx-auto">
          {lang === 'ar'
            ? 'عُد إلى لوحة التحكم لإدارة تطبيقاتك أو لبناء تطبيق جديد.'
            : lang === 'fr'
            ? 'Retournez au tableau de bord pour gérer vos applications ou en créer une nouvelle.'
            : 'Head back to your dashboard to manage your apps or start building a new one.'}
        </p>
        <div className="flex flex-wrap justify-center gap-3">
          <Link
            href="/dashboard"
            className="inline-flex items-center gap-2 px-6 py-3 bg-gradient-to-r from-indigo-500 to-pink-500 text-white font-bold text-sm rounded-xl shadow-lg shadow-indigo-500/25 hover:opacity-90 transition-opacity"
          >
            <LayoutDashboard className="h-4 w-4" />
            {lang === 'ar'
              ? 'لوحة التحكم'
              : lang === 'fr'
              ? 'Tableau de bord'
              : 'Go to Dashboard'}
          </Link>
          <Link
            href="/"
            className="inline-flex items-center gap-2 px-6 py-3 border border-slate-700 bg-slate-900 text-slate-300 font-semibold text-sm rounded-xl hover:bg-slate-800 transition-colors"
          >
            {lang === 'ar'
              ? 'إنشاء تطبيق جديد'
              : lang === 'fr'
              ? 'Créer une nouvelle app'
              : 'Create a new app'}
          </Link>
        </div>
      </div>

    </main>
  );
}

